import{_ as s,l as i,o as e,c as n,v as t,p as l,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"内核栈","description":"","frontmatter":{"title":"内核栈","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/kernel-stack.md","filePath":"cs/kernel-stack.md","lastUpdated":1789023840000}'),h={name:"cs/kernel-stack.md"};function _(m,a,f,A,u,E){const o=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="内核栈" tabindex="-1">内核栈 <a class="header-anchor" href="#内核栈" aria-label="Permalink to &quot;内核栈&quot;">​</a></h1><div class="epigraph"><p>每条内核线程一份不大的内核栈：陷入、系统调用与中断嵌套都压在这上面，而不是压在用户栈上。</p><footer>—— 据 Bovet and Cesati, Understanding the Linux Kernel；Love, LKD 整理</footer></div><p><a href="/cs/context-switch">上一课</a>保存用户寄存器并换页表根。硬件在陷入时还会切栈指针到内核。<a href="/cs/trapframe">trapframe</a> 住在这份栈上。缺口是把<strong>内核栈</strong>说清：为什么不能继续用用户栈、它有多深、溢出意味着什么。本课只钉这份栈，不写 FPU 保存策略。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>用户栈指针可被用户改成任意值，也可缺页。<a href="/cs/privilege-rings">特权级</a>下内核若在用户栈上建帧，用户能破坏返回地址。因此每条 <code>task_struct</code> 配独立内核栈（页级大小，通常两页量级）。缺口不是 clone 的共享位，而是：切换的核心动作之一是换 <code>sp</code> 到下一任务的内核栈，当前帧里的 trapframe 随之换掉。</p><p><span class="marginnote">内核栈小，禁止在内核路径上分配巨大局部数组。深递归与重入中断要靠独立 IRQ 栈或严格嵌套上限。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>创建任务：分配栈页，把初始栈顶写成「返回到用户或内核线程入口」的伪造帧。陷入：硬件或入口汇编切到该栈，压 trapframe，C 代码在此上继续。中断可在已处于内核时嵌套，继续压同一内核栈，或切到 per-CPU IRQ 栈以免溢。切换：保存当前内核 <code>sp</code> 到 PCB，载入下一任务的 <code>sp</code>。</p>',8)),(e(),l(p,null,{default:r(()=>[c(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E7%94%A8%E6%88%B7%E6%A0%88%22%5D%20--%3E%20TRAP%5B%22%E9%99%B7%E5%85%A5%3A%20%E5%88%87%E5%86%85%E6%A0%B8%E6%A0%88%22%5D%0A%20%20TRAP%20--%3E%20TF%5B%22trapframe%20%E5%9C%A8%E5%86%85%E6%A0%B8%E6%A0%88%22%5D%0A%20%20TF%20--%3E%20SW%5B%22%E5%88%87%E6%8D%A2%3A%20%E6%8D%A2%E5%86%85%E6%A0%B8%20sp%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><a href="/cs/nmi">NMI</a> 常用专用栈，避免在已损坏的任务内核栈上再跑看门狗。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>内核栈把内核执行与用户可写内存切开。同一 CPU 上瞬时只有一个内核 <code>sp</code> 活着；其余任务的栈是内存里的冷数据。溢出覆盖相邻的 <code>thread_info</code> 或金丝雀，内核必须检测而不能当成普通缺页——内核栈通常不按需扩展。这与用户栈增长是不同政策。</p><p>系统调用深度、持锁时的函数图，都受这几页限制；因此下半部才要短。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把各架构栈大小的 Kconfig 列完，不讨论 eBPF 在内核栈上的验证。用户态协程的栈是用户页，与本课对象不同。FPU 上下文常常太大，不宜每次都压进这几页，下一课惰性保存。</p><p>后课默认：内核执行在任务的内核栈上。浮点/向量寄存器是否每次切换都存，下一课讲 FPU 惰性保存。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>每任务一份内核栈；陷入不使用用户栈。</li><li>切换换内核 sp；栈小，禁止内核深递归。</li><li>大块 FPU 状态要惰性处理，下一课。</li><li>出处：Bovet and Cesati；Love, <em>LKD</em>。</li></ul>',9))])}const T=s(h,[["render",_]]);export{k as __pageData,T as default};
